"""Request authentication for the localhost backend.

* Every request must carry the per-launch random token generated by the
  Electron main process (``X-PDFEd-Token``).
* Requests with an ``Origin`` header (i.e. coming from a browser page) are
  rejected – protects against CSRF from web pages hitting localhost.
* The ``Host`` header must be the loopback address – protects against DNS
  rebinding.
"""
from __future__ import annotations

import secrets

from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import JSONResponse

ALLOWED_HOSTS = ("127.0.0.1", "localhost")


class TokenAuthMiddleware(BaseHTTPMiddleware):
    def __init__(self, app, token: str):
        super().__init__(app)
        self.token = token

    async def dispatch(self, request: Request, call_next):
        host = (request.headers.get("host") or "").split(":")[0]
        if host not in ALLOWED_HOSTS:
            return JSONResponse({"error": {"code": "forbidden", "message": "Invalid host"}}, status_code=403)
        if request.headers.get("origin"):
            return JSONResponse({"error": {"code": "forbidden", "message": "Browser requests are not allowed"}},
                                status_code=403)
        supplied = request.headers.get("x-pdfed-token", "")
        if not self.token or not secrets.compare_digest(supplied, self.token):
            return JSONResponse({"error": {"code": "unauthorized", "message": "Invalid token"}}, status_code=401)
        return await call_next(request)
